import type { ColumnDef, DbObject } from "../model";

/**
 * DDL do Firebird a partir do modelo do designer. O Firebird altera a tabela no lugar (`ALTER TABLE`); não há schemas (até a versão 4)
 * e os nomes entre aspas distinguem maiúsculas de minúsculas, então um nome novo escrito só em minúsculas vira maiúsculo (o que o
 * Firebird faria com um nome sem aspas); os nomes que já existem seguem exatamente como estão.
 *
 * Auto incremento: a partir do Firebird 3, tabela nova usa `GENERATED BY DEFAULT AS IDENTITY`. No 2.5, e numa coluna que já existe
 * (a identidade não se liga depois), usa um gerador e um gatilho `BEFORE INSERT` que preenche a coluna quando ela vem vazia.
 */

export const FIREBIRD_TYPES = [
  "bigint", "blob", "blob sub_type text", "boolean", "char", "date", "decimal", "double precision", "float", "integer", "numeric", "smallint", "time", "timestamp", "varchar",
];

/** Os tipos que numeram sozinhos. */
const AUTO_TYPES = new Set(["smallint", "integer", "bigint", "int128"]);
export const isAutoType = (type: string) => AUTO_TYPES.has(type.trim().toLowerCase());

/** A identidade (`GENERATED ... AS IDENTITY`) existe a partir do Firebird 3; o `DROP IDENTITY`, a partir do 4. */
export const hasIdentity = (version: number) => version >= 3_000_000;
export const canDropIdentity = (version: number) => version >= 4_000_000;

/** Entre aspas, como o Firebird quer os nomes que não são maiúsculos simples. */
export const q = (name: string) => `"${name.replace(/"/g, '""')}"`;

/** Nome novo escrito só em minúsculas (letras, dígitos e `_`) vira maiúsculo; qualquer outro nome fica como foi escrito. */
export const norm = (name: string) => (/^[a-z_][a-z0-9_$]*$/.test(name) ? name.toUpperCase() : name);

const normList = (fields: string) => fields.split(",").map((f) => norm(f.trim())).join(", ");

/** A tabela nova com todos os nomes (tabela, colunas, chaves, índices e restrições) no formato do Firebird. */
export function normalizeFirebirdObject(t: DbObject): DbObject {
  return {
    ...t,
    name: norm(t.name),
    columns: (t.columns ?? []).map((c) => ({ ...c, name: norm(c.name) })),
    indexes: (t.indexes ?? []).map((i) => ({ ...i, name: norm(i.name), fields: normList(i.fields) })),
    uniques: (t.uniques ?? []).map((u) => ({ ...u, name: norm(u.name), fields: normList(u.fields) })),
    checks: (t.checks ?? []).map((c) => ({ ...c, name: norm(c.name) })),
    foreignKeys: (t.foreignKeys ?? []).map((f) => ({ ...f, name: norm(f.name), fields: normList(f.fields), refTable: norm(f.refTable), refFields: normList(f.refFields) })),
  };
}

const lit = (s: string) => `'${s.replace(/'/g, "''")}'`;

export function firebirdColumnType(c: ColumnDef): string {
  const t = c.type.trim().toLowerCase();
  if (t === "varchar") return `varchar(${c.length > 0 ? c.length : 255})`;
  if (t === "char") return `char(${c.length > 0 ? c.length : 1})`;
  if (t === "numeric" || t === "decimal") return `${t}(${c.length > 0 ? c.length : 18}, ${c.decimal > 0 ? c.decimal : 0})`;
  return t;
}

/** Os nomes do gerador e do gatilho que numeram uma coluna (até 31 caracteres, o limite do Firebird 2.5). */
const fit = (base: string, suffix: string) => (base.length + suffix.length <= 31 ? base + suffix : base.slice(0, 31 - suffix.length) + suffix);
export const generatorName = (table: string, column: string) => fit(`GEN_${table}_${column}`, "");
export const triggerName = (table: string, column: string) => fit(`${table}_${column}`, "_BI");

/** Gerador + gatilho que preenchem a coluna quando o `INSERT` não a informa. */
function numberingStatements(table: string, column: string, seed: boolean): string[] {
  const gen = generatorName(table, column);
  const out = [`CREATE GENERATOR ${q(gen)}`];
  // Numa tabela com linhas, o gerador começa no maior valor que a coluna já tem.
  if (seed) out.push(`EXECUTE BLOCK AS\nDECLARE v BIGINT;\nBEGIN\n  SELECT COALESCE(MAX(${q(column)}), 0) FROM ${q(table)} INTO :v;\n  v = GEN_ID(${q(gen)}, :v);\nEND`);
  out.push(`CREATE TRIGGER ${q(triggerName(table, column))} FOR ${q(table)}\nACTIVE BEFORE INSERT POSITION 0\nAS\nBEGIN\n  IF (NEW.${q(column)} IS NULL) THEN\n    NEW.${q(column)} = GEN_ID(${q(gen)}, 1);\nEND`);
  return out;
}

/** O gatilho e o gerador de uma coluna que já numera por esse jeito (`gatilho|gerador`), ou os nomes do padrão. */
const sourceOf = (c: ColumnDef): [string, string] | null => {
  const [trg, gen] = (c.autoSource ?? "").split("|");
  return trg && gen ? [trg, gen] : null;
};

/** Valor padrão: literal, variável de contexto ou número vai como está; texto solto vira literal. */
const defaultExpr = (v: string) => {
  const t = v.trim().replace(/^default\s+/i, "");
  if (/^(null|true|false|user|current_user|current_role|current_date|current_time|current_timestamp|now|today|tomorrow|yesterday)$/i.test(t) || /^[+-]?\d+(\.\d+)?$/.test(t) || /^'([^']|'')*'$/.test(t)) return t;
  return lit(t);
};

interface NameCtx {
  /** O nome que a coluna `i` tem (ou terá) no banco. */
  eff: (c: ColumnDef, i: number) => string;
}

const fieldList = (fields: string, cols: ColumnDef[], ctx: NameCtx) =>
  fields
    .split(",")
    .map((f) => f.trim())
    .filter(Boolean)
    .map((f) => {
      const i = cols.findIndex((c) => c.name === f);
      const j = i >= 0 ? i : cols.findIndex((c) => c.name.toLowerCase() === f.toLowerCase());
      return q(j >= 0 ? ctx.eff(cols[j], j) : norm(f));
    })
    .join(", ");

function columnLine(c: ColumnDef, name: string, identity: boolean): string {
  const base = `${q(name)} ${firebirdColumnType(c)}`;
  if (identity) return `${base} GENERATED BY DEFAULT AS IDENTITY`;
  let line = base;
  if (c.default) line += ` DEFAULT ${defaultExpr(c.default)}`;
  if (c.notNull || c.key) line += " NOT NULL";
  return line;
}

function fkLine(table: string, f: NonNullable<DbObject["foreignKeys"]>[number], cols: ColumnDef[], ctx: NameCtx, nameOf: (n: string) => string): string {
  const refs = f.refFields.trim() ? ` (${f.refFields.split(",").map((x) => q(x.trim())).filter((x) => x !== '""').join(", ")})` : "";
  let line = `${f.name ? `CONSTRAINT ${q(nameOf(f.name))} ` : ""}FOREIGN KEY (${fieldList(f.fields, cols, ctx)}) REFERENCES ${q(f.refTable)}${refs}`;
  if (f.onDelete && f.onDelete !== "NO ACTION") line += ` ON DELETE ${f.onDelete}`;
  if (f.onUpdate && f.onUpdate !== "NO ACTION") line += ` ON UPDATE ${f.onUpdate}`;
  void table;
  return line;
}

const indexSql = (target: string, name: string, fields: string, unique: boolean) => `CREATE ${unique ? "UNIQUE " : ""}INDEX ${q(name)} ON ${target} (${fields})`;

export function createTableStatementsFirebird(table: DbObject, version: number, nameOverride?: string): string[] {
  const name = norm(nameOverride ?? table.name);
  const target = q(name);
  const cols = table.columns ?? [];
  const ctx: NameCtx = { eff: (c) => norm(c.name) };
  const useIdentity = hasIdentity(version);
  const lines = cols.map((c) => columnLine(c, ctx.eff(c, 0), !!c.autoInc && isAutoType(c.type) && useIdentity));
  const keys = cols.filter((c) => c.key).sort((a, b) => (a.key ?? 0) - (b.key ?? 0));
  if (keys.length) lines.push(`PRIMARY KEY (${keys.map((k) => q(norm(k.name))).join(", ")})`);
  for (const u of table.uniques ?? []) if (fieldList(u.fields, cols, ctx)) lines.push(`${u.name ? `CONSTRAINT ${q(norm(u.name))} ` : ""}UNIQUE (${fieldList(u.fields, cols, ctx)})`);
  for (const c of table.checks ?? []) if (c.expression.trim()) lines.push(`${c.name ? `CONSTRAINT ${q(norm(c.name))} ` : ""}CHECK (${c.expression.trim()})`);
  for (const f of table.foreignKeys ?? []) if (fieldList(f.fields, cols, ctx) && f.refTable) lines.push(fkLine(name, f, cols, ctx, norm));
  const out = [`CREATE TABLE ${target} (\n  ${lines.join(",\n  ")}\n)`];
  for (const i of table.indexes ?? []) if (i.name && fieldList(i.fields, cols, ctx)) out.push(indexSql(target, norm(i.name), fieldList(i.fields, cols, ctx), i.unique));
  if (!useIdentity) for (const c of cols) if (c.autoInc && isAutoType(c.type)) out.push(...numberingStatements(name, norm(c.name), false));
  return out;
}

export interface FirebirdAlterPlan { sql: string; statements: string[]; destructive: boolean }

const sameType = (a: ColumnDef, b: ColumnDef) => firebirdColumnType(a) === firebirdColumnType(b);
const same = (a?: string, b?: string) => (a ?? "").trim().replace(/^default\s+/i, "") === (b ?? "").trim().replace(/^default\s+/i, "");

/**
 * Comandos para levar `original` ao que o designer montou em `next`. `origNames[i]` é o nome que a coluna `i` de `next` tinha ao
 * abrir (vazio = coluna nova).
 */
export function alterStatementsFirebird(original: DbObject, next: DbObject, origNames: (string | undefined)[], version: number): FirebirdAlterPlan {
  const table = original.name;
  const target = q(table);
  const oldCols = original.columns ?? [];
  const newCols = next.columns ?? [];
  const out: string[] = [];
  let destructive = false;
  const kept = new Set(origNames.filter(Boolean));
  const ctx: NameCtx = { eff: (c, i) => (origNames[i] === c.name ? c.name : norm(c.name)) };
  const existing = (list: { name: string }[] | undefined) => new Set((list ?? []).map((x) => x.name));
  const oldNames = new Set([...existing(original.foreignKeys), ...existing(original.uniques), ...existing(original.checks), ...existing(original.indexes)]);
  /** Nome de restrição ou índice: o que já existe fica; o novo vira maiúsculo. */
  const nameOf = (n: string) => (oldNames.has(n) ? n : norm(n));
  const useIdentity = hasIdentity(version);

  const byName = <T extends { name: string }>(l: T[] | undefined) => new Map((l ?? []).map((x) => [x.name, x]));
  // As restrições e índices que saem ou mudam caem antes das colunas.
  const adds: string[] = [];
  const diff = <T extends { name: string }>(a: T[] | undefined, b: T[] | undefined, key: (x: T) => string, drop: (x: T) => string, add: (x: T) => string | null) => {
    const before = byName(a);
    const after = byName(b);
    for (const [n, x] of before) {
      const y = after.get(n);
      if (!y || key(x) !== key(y)) out.push(drop(x));
    }
    for (const [n, y] of after) {
      const x = before.get(n);
      if (!x || key(x) !== key(y)) {
        const sql = add(y);
        if (sql) adds.push(sql);
      }
    }
  };
  const resolved = (fields: string) => fields.split(",").map((f) => f.trim().toLowerCase()).filter(Boolean).join(",");
  diff(original.foreignKeys, next.foreignKeys, (f) => `${resolved(f.fields)}|${f.refTable}|${resolved(f.refFields)}|${f.onDelete}|${f.onUpdate}`, (f) => `ALTER TABLE ${target} DROP CONSTRAINT ${q(f.name)}`,
    (f) => (fieldList(f.fields, newCols, ctx) && f.refTable ? `ALTER TABLE ${target} ADD ${fkLine(table, f, newCols, ctx, nameOf)}` : null));
  diff(original.uniques, next.uniques, (u) => resolved(u.fields), (u) => `ALTER TABLE ${target} DROP CONSTRAINT ${q(u.name)}`,
    (u) => (fieldList(u.fields, newCols, ctx) ? `ALTER TABLE ${target} ADD ${u.name ? `CONSTRAINT ${q(nameOf(u.name))} ` : ""}UNIQUE (${fieldList(u.fields, newCols, ctx)})` : null));
  diff(original.checks, next.checks, (c) => c.expression.trim(), (c) => `ALTER TABLE ${target} DROP CONSTRAINT ${q(c.name)}`,
    (c) => (c.expression.trim() ? `ALTER TABLE ${target} ADD ${c.name ? `CONSTRAINT ${q(nameOf(c.name))} ` : ""}CHECK (${c.expression.trim()})` : null));
  diff(original.indexes, next.indexes, (i) => `${resolved(i.fields)}|${i.unique}`, (i) => `DROP INDEX ${q(i.name)}`,
    (i) => (i.name && fieldList(i.fields, newCols, ctx) ? indexSql(target, nameOf(i.name), fieldList(i.fields, newCols, ctx), i.unique) : null));

  // Chave primária: se mudou, cai antes das colunas e volta depois.
  const oldKey = oldCols.filter((c) => c.key).sort((a, b) => (a.key ?? 0) - (b.key ?? 0)).map((c) => c.name);
  const newKeyOrig = newCols.map((c, i) => ({ c, n: origNames[i] ?? c.name })).filter((x) => x.c.key).sort((a, b) => (a.c.key ?? 0) - (b.c.key ?? 0)).map((x) => x.n);
  const pkChanged = JSON.stringify(oldKey) !== JSON.stringify(newKeyOrig);
  if (pkChanged && oldKey.length && original.pkName) out.push(`ALTER TABLE ${target} DROP CONSTRAINT ${q(original.pkName)}`);

  // Auto incremento que sai: da coluna que perdeu a numeração e da que foi apagada.
  const dropNumbering = (o: ColumnDef) => {
    const src = sourceOf(o);
    if (src) out.push(`DROP TRIGGER ${q(src[0])}`, `DROP GENERATOR ${q(src[1])}`);
    else if (o.identity && canDropIdentity(version)) out.push(`ALTER TABLE ${target} ALTER COLUMN ${q(o.name)} DROP IDENTITY`);
  };
  for (const o of oldCols) {
    if (kept.has(o.name)) continue;
    if (o.identity && sourceOf(o)) dropNumbering(o);
    out.push(`ALTER TABLE ${target} DROP ${q(o.name)}`);
    destructive = true;
  }
  newCols.forEach((c, i) => {
    const o = oldCols.find((x) => x.name === origNames[i]);
    if (o && !!o.identity && !c.autoInc) dropNumbering(o);
  });

  const late: string[] = [];
  newCols.forEach((c, i) => {
    const o = oldCols.find((x) => x.name === origNames[i]);
    const name = ctx.eff(c, i);
    if (!o) {
      const identity = !!c.autoInc && isAutoType(c.type) && useIdentity;
      out.push(`ALTER TABLE ${target} ADD ${columnLine(c, name, identity)}`);
      if (c.autoInc && isAutoType(c.type) && !useIdentity) late.push(...numberingStatements(table, name, false));
      return;
    }
    let current = o.name;
    if (o.name !== name) {
      out.push(`ALTER TABLE ${target} ALTER COLUMN ${q(o.name)} TO ${q(name)}`);
      current = name;
    }
    if (!sameType(o, c)) {
      out.push(`ALTER TABLE ${target} ALTER COLUMN ${q(current)} TYPE ${firebirdColumnType(c)}`);
      destructive = true;
    }
    if (!same(o.default, c.default)) out.push(c.default ? `ALTER TABLE ${target} ALTER COLUMN ${q(current)} SET DEFAULT ${defaultExpr(c.default)}` : `ALTER TABLE ${target} ALTER COLUMN ${q(current)} DROP DEFAULT`);
    const wasNotNull = !!o.notNull || !!o.key;
    const isNotNull = !!c.notNull || !!c.key || !!c.autoInc;
    if (wasNotNull !== isNotNull) {
      if (hasIdentity(version)) out.push(`ALTER TABLE ${target} ALTER COLUMN ${q(current)} ${isNotNull ? "SET" : "DROP"} NOT NULL`);
      else out.push(`UPDATE RDB$RELATION_FIELDS SET RDB$NULL_FLAG = ${isNotNull ? "1" : "NULL"} WHERE RDB$RELATION_NAME = ${lit(table)} AND RDB$FIELD_NAME = ${lit(current)}`);
    }
    // Numeração ligada numa coluna que já existe: gerador + gatilho (a identidade não se acrescenta depois).
    if (c.autoInc && !o.identity && isAutoType(c.type)) late.push(...numberingStatements(table, current, true));
  });

  const newKeyNow = newCols.map((c, i) => ({ c, n: ctx.eff(c, i) })).filter((x) => x.c.key).sort((a, b) => (a.c.key ?? 0) - (b.c.key ?? 0)).map((x) => x.n);
  if (pkChanged && newKeyNow.length) out.push(`ALTER TABLE ${target} ADD PRIMARY KEY (${newKeyNow.map(q).join(", ")})`);
  out.push(...late, ...adds);

  return { sql: out.map((s) => `${s};`).join("\n"), statements: out, destructive };
}

/** Criar a view; ao alterar, `CREATE OR ALTER VIEW` (Firebird 2.5 em diante). */
export function viewStatementsFirebird(name: string, definition: string, replace: boolean): string[] {
  return [`${replace ? "CREATE OR ALTER" : "CREATE"} VIEW ${q(replace ? name : norm(name))} AS\n${definition.trim().replace(/;+\s*$/, "")}`];
}

export { lit as firebirdLiteral };
